-- One example sentence for each active word in the SAT deck (822 words).
-- Fills only empty examples, and only where both id and word still match.
-- Also copies the example onto students' saved copies of those words when
-- their copy has no example yet (anything a student typed is left alone).

BEGIN;

CREATE TEMP TABLE bank_examples (id uuid, word text, example text) ON COMMIT DROP;


UPDATE pet_word_bank b
SET example = e.example
FROM bank_examples e
WHERE b.id = e.id
  AND b.word = e.word
  AND nullif(trim(b.example), '') IS NULL;

UPDATE saved_words s
SET example = e.example
FROM bank_examples e
WHERE s.bank_word_id = e.id
  AND nullif(trim(s.example), '') IS NULL;

COMMIT;
